import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as r,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"推理模型与 Test-Time Compute（桥接）","description":"「让模型多想一会儿」是与模型规模并列的性能轴——本页给应用工程师位置感：思考与行动是两种消耗（何时用推理模型、何时用 agent 循环）、延迟结构、计费与停止条件；训练侧原理桥接 Learn LLM。","frontmatter":{"title":"推理模型与 Test-Time Compute（桥接）","description":"「让模型多想一会儿」是与模型规模并列的性能轴——本页给应用工程师位置感：思考与行动是两种消耗（何时用推理模型、何时用 agent 循环）、延迟结构、计费与停止条件；训练侧原理桥接 Learn LLM。","domain":"tech","tags":["tech","reasoning","test-time-compute","bridge"],"navOrder":92,"topicId":"reasoning-ttc","layer":"9","status":"bridge","nodeType":"boundary","owner":"learn-ai","externalOwners":[{"site":"llm","url":"https://llm.zenheart.site/"}],"lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"zh/tech/09-advanced/reasoning-ttc.md","filePath":"zh/tech/09-advanced/reasoning-ttc.md","lastUpdated":1788429430000}'),n={name:"zh/tech/09-advanced/reasoning-ttc.md"};function i(l,t,d,s,h,c){return r(),a("div",null,[...t[0]||(t[0]=[o('<blockquote><p><strong>所在组</strong>：进阶（桥接） ｜ <strong>上一组出口</strong>：能用发布门与版本化纪律长期运行 ｜ <strong>本页出口</strong>：知道该主题影响哪个工程决策、何时去 Learn LLM</p></blockquote><h1 id="推理模型与-test-time-compute-桥接" tabindex="-1">推理模型与 Test-Time Compute（桥接） <a class="header-anchor" href="#推理模型与-test-time-compute-桥接" aria-label="Permalink to &quot;推理模型与 Test-Time Compute（桥接）&quot;">​</a></h1><blockquote><p><strong>桥接页</strong>：推理模型（o1/R1 一系）的训练方法——长思维链 RL、GRPO、可验证奖励——的推导在 <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a>（第 10 章 · 后训练；推理侧预算见第 9 章）。本仓只保留应用侧的位置感：<strong>它是一种新的消耗品，你要决定何时买、买多少、怎么停。</strong></p></blockquote><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p><strong>解决什么问题</strong>：传统缩放把钱花在训练侧（更大模型）；test-time compute 把钱花在推理侧——重复采样、搜索、更长的思考链——换取单次请求更高的质量。推理模型把这条轴产品化：同一个模型，想得越久（推理 token 越多），平均质量越高。</p><p><strong>为什么应用工程师要有位置感</strong>：这不是「换个更强的模型」，而是多了一个<strong>运行时可调的预算参数</strong>。它直接改变三件事：模型选型的权衡空间（小模型多想 vs 大模型直答）、单位成本结构（按思考量计费）、产品交互契约（延迟与停止条件）。</p><h2 id="_2-使用" tabindex="-1">2. 使用 <a class="header-anchor" href="#_2-使用" aria-label="Permalink to &quot;2. 使用&quot;">​</a></h2><h3 id="思考与行动是两种消耗" tabindex="-1">思考与行动是两种消耗 <a class="header-anchor" href="#思考与行动是两种消耗" aria-label="Permalink to &quot;思考与行动是两种消耗&quot;">​</a></h3><p>推理模型的「思考」（模型内部延长推理）与 agent 的「行动循环」（调用工具、观测、再决策）是<strong>两种不同的质量提升手段</strong>，都花推理预算，但不可互换：</p><table tabindex="0"><thead><tr><th>手段</th><th>花在哪</th><th>擅长</th><th>不擅长</th></tr></thead><tbody><tr><td>思考（reasoning / TTC）</td><td>单次调用内的推理 token</td><td>可在「脑内」完成的问题：数学、规划、代码逻辑、多约束权衡</td><td>需要新事实（→检索）或需要改变外部状态（→工具）</td></tr><tr><td>行动循环（agent loop）</td><td>多次调用 + 工具执行</td><td>需要与外部世界交互：查数据、改系统、长流程</td><td>纯封闭推理题上比思考更贵更慢</td></tr></tbody></table><p>选型顺序：<strong>能一次想清楚的不起循环；需要新信息或副作用的循环不能被思考替代</strong>。两者也可组合（每步行动前短思考），但每层都要有独立预算与停止条件。</p><h3 id="对产品的三个直接影响" tabindex="-1">对产品的三个直接影响 <a class="header-anchor" href="#对产品的三个直接影响" aria-label="Permalink to &quot;对产品的三个直接影响&quot;">​</a></h3><ol><li><strong>延迟结构</strong>：思考时间随难度波动且可能很长——首字时间（TTFT）不再可控。交互设计要么改为「思考中」的显式状态，要么给思考设上限。</li><li><strong>计费</strong>：推理 token 是真实成本项，且用量由模型自己决定——成本从「按请求计」变成「按请求 × 思考量计」，预算熔断（→<a href="./../08-production/cost-performance.html">成本与性能</a>）从可选变必选。</li><li><strong>停止条件</strong>：何时切断思考是产品决策——超时、token 上限、或预算强制（budget forcing）类机制。没有停止条件的思考型调用在异常输入上会失控烧钱。</li></ol><h2 id="_3-原理" tabindex="-1">3. 原理 <a class="header-anchor" href="#_3-原理" aria-label="Permalink to &quot;3. 原理&quot;">​</a></h2><p>（本段刻意极简：训练与缩放律推导归 Learn LLM。）</p><p>一句话路线：重复采样可提升覆盖率（采样越多、命中的问题越多，但有验证器才兑现）→ 按难度分配推理预算优于均匀分配 → RL 训练出「内化了的长思考」（o1/R1 一系）→ 思考长度成为可外部干预的控制量。深水区：Learn LLM 第 10 章（后训练/RL）、第 9 章（推理与预算）。</p><h2 id="_4-开发" tabindex="-1">4. 开发 <a class="header-anchor" href="#_4-开发" aria-label="Permalink to &quot;4. 开发&quot;">​</a></h2><p><strong>症状 → 去哪</strong>：</p><ul><li>「延迟方差大、偶发超长响应」→ 本区立场：给思考设停止条件；工程落点在<a href="./../08-production/cost-performance.html">成本与性能</a>的熔断与预算。</li><li>「模型单步老出错，想让它多想」→ 先确认错误类型：封闭推理题用推理模型/高思考预算；缺事实去 <a href="./../04-grounding/">04-grounding</a>；要执行去 <a href="./../05-action/tool-calling.html">05-action</a>。</li><li>「agent 每步都开最大思考，成本爆炸」→ 分层预算：规划步高预算、执行步低预算——落点在 <a href="./../06-agent-systems/agent-runtime.html">06-agent-systems</a> 的运行时配置。</li><li>想懂 RL 怎么造出推理行为 → Learn LLM 第 10 章。</li></ul><h2 id="_5-资料库" tabindex="-1">5. 资料库 <a class="header-anchor" href="#_5-资料库" aria-label="Permalink to &quot;5. 资料库&quot;">​</a></h2><p>一手源（只引编号，不复述内容）：</p><table tabindex="0"><thead><tr><th>名称</th><th>来源</th><th>标识</th></tr></thead><tbody><tr><td>Large Language Monkeys（重复采样缩放）</td><td>Stanford / Google DeepMind</td><td>arXiv:2407.21787</td></tr><tr><td>Scaling LLM Test-Time Compute Optimally</td><td>UC Berkeley / Google DeepMind</td><td>arXiv:2408.03314</td></tr><tr><td>DeepSeek-R1（纯 RL 激发推理）</td><td>DeepSeek-AI</td><td>arXiv:2501.12948</td></tr><tr><td>s1: Simple test-time scaling（budget forcing）</td><td>Stanford / UW 等</td><td>arXiv:2501.19393</td></tr></tbody></table><p>（retrievedAt 2026-09-01；各厂商推理模型的当前参数与定价以其官方文档实时为准。）</p><h3 id="learn-ai-到此为止-继续去哪" tabindex="-1">learn-ai 到此为止 / 继续去哪 <a class="header-anchor" href="#learn-ai-到此为止-继续去哪" aria-label="Permalink to &quot;learn-ai 到此为止 / 继续去哪&quot;">​</a></h3><ul><li>长思维链 RL、GRPO、推理缩放律：<a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a> 第 10 章（后训练）。</li><li>推理预算与延迟的工程收口：<a href="./../08-production/cost-performance.html">成本与性能</a>、<a href="./../08-production/deployment.html">部署与发布</a>。</li></ul>',25)])])}const f=e(n,[["render",i]]);export{b as __pageData,f as default};
